import {packFingerprint} from './hint-economy.js';

// Original editorial clues in campaign order. Fingerprints prevent a different
// import from picking up a clue just because it claims the same campaign/slot.
const strategies=new Map([
 [1,new Map([
  ["14qwkte",["Zacznij od czerwonego rezonatora. Wyobraź sobie linię schodzącą od niego do rzędu wiązki. Jedno lustro na przecięciu wystarczy.","Work back from the red receiver to the beam's row. A single mirror at their intersection can make the turn."]],
  ["1ltibi7",["Czerwona droga potrzebuje jednego zakrętu. Niebieską poprowadź najpierw w dół, żeby wróciła w lewo na wysokości swojego celu.","Red needs one turn. Send blue down first so it can head left again at its receiver's height."]],
  ["8dzpcu",["Pomyśl o niebieskim, zielonym i czerwonym jak o trzech prostych odcinkach. Każda para powinna przeciąć się przy innym celu, tworząc odpowiednio cyjan, magentę i żółty.","Think in three separate beam lines. Make a different pair cross at each receiver to form cyan, magenta and yellow."]],
  ["wtx8uf",["Pierwszy rozdzielacz zachowuje zieloną trasę w prawo i wysyła odnogę do góry. Pozostałe rozdzielacze wykorzystają tę odnogę do zasilenia lewej części.","The first splitter keeps green headed right and sends a branch upward. Use that branch to feed the receivers on the left."]],
  ["1hx4ko7",["Dwa żółte cele potrzebują tych samych dwóch składowych. Skieruj oba kolory przez wspólny rozdzielacz z różnych stron, aby uzyskać drogę w górę i w dół.","Both yellow receivers need the same two channels. Feed red and green through one splitter from different sides to build the upward and downward routes."]],
  ["kv5gpo",["Rozdaj czerwony w górę, a niebieski w dół. W środku doprowadź po jednej odnodze obu kolorów do magenty.","Branch red upward and blue downward. Bring one branch of each together at the magenta receiver in the middle."]],
  ["1mid7hw",["Korytarze zostawiają niebieskiemu ukośne wyjście po lewej, czerwonemu po prawej. Szukaj zakrętów zakrzywiacza, które pozwolą przejść między ścianami.","The walls leave a diagonal exit for blue on the left and red on the right. Look for bender turns that fit through those passages."]],
  ["1dpixkp",["Z niebieskiego źródła zrób ukośną trasę ku lewej górze. Na niej rozstaw rozdzielacze, które wypuszczą odnogi po obu stronach trasy.","Establish a diagonal blue route toward the upper left. Put splitters on it to branch toward receivers on both sides."]],
  ["16dcfxh",["Zacznij od wejść do kanałów. Zakrzywiacz przy górnej części kieruje zielony po skosie w dół i w prawo zgodnie z ich osią.","Start with the conduit entrances. A bender in the upper part turns green down and right to match their axis."]],
  ["4ogo7s",["Odtwarzaj czerwony szlak od zakrętu do zakrętu. Szukaj odcinków, które oświetlą kilka celów po drodze, zanim wiązka skręci ponownie.","Build the red route one bend at a time. Look for lanes that can light several receivers before the beam turns again."]],
  ["1dp27eb",["Szukaj wąskiego przejścia, które czerwony i zielony mogą wykorzystać z różnych stron. Wspólny zakrzywiacz potrafi wysłać je na dwie osobne przekątne.","Look for a narrow passage red and green can approach from different sides. A shared bender can send them onto separate diagonals."]],
  ["1rypgkh",["W środku wykorzystaj spotkanie czerwonej i niebieskiej trasy. Rozdzielacz może jednocześnie utrzymać jedną odnogę każdego koloru i wysłać po drugiej do bocznych celów.","Let the red and blue routes meet near the middle. A splitter can preserve one branch of each and send the others toward the side receivers."]],
  ["1ilfiuy",["Niebieski potrzebuje trasy do lewej strony oraz odnogi w dół po prawej. Zarezerwuj rozdzielacz dla niebieskiego, a czerwony prowadź osobnymi zakrętami.","Blue needs a route to the left and a downward branch on the right. Reserve the splitter for blue and route red through separate turns."]],
  ["1o5oy6t",["Biały w środku to osobne zadanie od zielonego, niebieskiego i czerwonego. Poprowadź biały po przekątnej od dołu; pozostałe kolory ustaw pod ich własne cele.","Treat the white receiver separately first. Bring white in diagonally from below, then route green, blue and red to their individual targets."]],
  ["1pf16m6",["Zachowaj drogę białego przez kanał. Rozdzielacze przed nim pozwolą wysłać światło w górę i w dół, a filtry wydobędą potrzebne pojedyncze kolory.","Keep the white route through the conduit. Split white upward and downward beforehand so the filters can pick out the individual channels."]],
  ["kquhdv",["Przez białe cele przeprowadź ciągłą wiązkę z białego lasera. Czerwone i zielone odcinki można posłać przez ten sam zakrzywiacz z dwóch kierunków.","Run a continuous white beam through the white receivers. Route the red and green stretches through one bender from two directions."]],
  ["m0qvwz",["Nadaj każdemu kolorowi własne odgałęzienie. Na białej trasie ustaw filtry w miejscach, w których rozdzielacze mogą dalej powielać już pojedynczy kolor.","Give each channel its own branch. Put filters where downstream splitters can duplicate the isolated red, blue or green."]],
  ["1d4htkl",["Najpierw obsłuż białe cele, zachowując pełne widmo. Pryzmat skieruj na dalszym etapie tak, by rozprowadził trzy kolory w stronę dolnych celów.","Light the white receivers while keeping all three channels together. Use the prism farther along the route to send the components to the lower receivers."]],
  ["jsommp",["Rozdzielacz daje czerwonej i niebieskiej wiązce po dwie drogi. Pryzmaty potraktuj jak selektywne zakręty, bo ten sam kąt wejścia daje obu barwom inne wyjście.","The splitter gives red and blue two paths each. Use the prisms as selective bends because the same entry angle sends the two colours in different directions."]],
  ["14r7oel",["Biały cel w lewym dolnym obszarze potrzebuje trzech kolorów. Zacznij od ostatniego zakrzywiacza, do którego wszystkie mogą dojść wspólnym odcinkiem z prawej.","The white receiver in the lower left needs all three colours. Work back from the last bender that can receive them along a shared stretch from the right."]],
  ["1tzbcmt",["Pryzmat może obsłużyć obie białe wiązki, jeśli wpadają pod różnymi kątami. Rezerwuj niebieski i zielony dla celów cyjanowych, a czerwony odprowadź osobno.","One prism can serve both white beams when they enter at different angles. Pair blue with green for cyan, and send red to its separate targets."]],
  ["1iqo5ou",["Połącz trzy składowe na wspólnych przekątnych, żeby zasilić kilka białych celów. Obrót pryzmatu powinien kierować kolory wzdłuż kanałów prowadzących do górnych celów.","Build white by overlapping the three components along shared diagonals. Orient the prism to send colours down the conduits leading to the upper receivers."]],
  ["18tqdhi",["Zbuduj pierwszy zielony odcinek po przekątnej. Dwa przejścia przez Dopplera pozwolą na tej samej klasie przekątnych uzyskać najpierw niebieski, później czerwony.","Build the first green diagonal. Two Doppler interactions can turn that route blue and then red."]],
  ["1c4qiwf",["Prowadź czerwień do miejsc, gdzie tor potrzebuje kolejno zieleni i niebieskiego. Strona wejścia do Dopplera zdecyduje, czy zrobisz pożądany krok po widmie.","Take red to the junctions where the path needs green and blue in turn. The Doppler input side determines which way you step around the colour cycle."]],
  ["1svpyyx",["Podziel planszę na dwie trasy. Czerwień z lewej potrzebuje przemiany w niebieski na górę, a niebieski z prawej może później zmienić się w zieleń na dole.","Treat the board as two routes. Turn the red from the left into blue for the upper area, and convert blue from the right into green lower down."]],
  ["sf7l52",["Rozdziel niebieską wiązkę splątywaczem na lewo i prawo. Zbadaj, co stanie się z drugą odnogą, kiedy tylko jedna przejdzie przez Dopplera.","Use the tangler to make left and right blue branches. Watch the far branch when only its partner passes through the Doppler."]],
  ["1uuxl0k",["Po splątaniu dwie przeciwne trasy mają dać różne kolory. Ustaw Dopplery z myślą o parze, a potem odbij oba tory wzdłuż bocznych krawędzi.","After entanglement the opposite paths must reach different colours. Set the Dopplers with the pair in mind, then reflect both routes along the sides."]],
  ["1qd4xmo",["Ze splątywacza poprowadź niebieski w górę i w dół. Na dolnej drodze przydadzą się zmiany koloru; obserwuj ich skutki także przy górnych celach.","Send blue up and down from the tangler. Make colour changes on the lower route while watching their effect on the upper receivers."]],
  ["19kqzqh",["Najpierw rozdziel zielony na dwie przeciwne odnogi i zmień widmo pary. Magenta po lewej powstaje z dwóch tras, więc czerwone i niebieskie dojście zaplanuj osobno.","Split green into opposite branches and shift the pair. The left magenta receiver needs both a red and a blue arrival."]],
  ["1p7q33o",["Rozdziel biały splątywaczem, zanim zaczniesz zmieniać składowe. Jedna odnoga ma zasilić biały cel, druga może trafić do pryzmatu, który rozprowadzi kolory na dole.","Split white with the tangler before changing its channels. Keep one branch for white and let the prism distribute the lower colours on the other."]],
  ["xko5pz",["Cyjan potrzebuje niebieskiego i zielonego. Zbuduj tę parę przy górnym splątywaczu, a na odnodze ku prawej użyj Dopplera, by uzyskać czerwień dla żółtego lub magenty.","Pair blue and green for cyan near the upper tangler. Use the Doppler on the right branch to obtain the red needed for yellow or magenta."]],
  ["xg25ne",["Doprowadź czerwony do splątywacza po skosie. Dwa wyjścia rozdzielą zadania: jedno prowadzi do czerwonych celów, drugie pozwala uzyskać niebieski i zielony przez zmianę widma.","Feed the tangler diagonally with red. One output can serve red while the other helps create blue and green through colour shifts."]],
  ["1fqinpy",["Zacznij od odbiorników mieszanych. Prowadź potrzebne kolory przez osie kanałów, aby dochodziły niezależnie do magenty, żółtego i cyjanu.","Start with the mixed receivers. Use the conduit axes to bring separate colours to magenta, yellow and cyan."]],
  ["1lsfcmn",["Środkowy rozdzielacz może obsłużyć promień w obie strony. Poprowadź czerwony w obwód, który ponownie zasila rozdzielacz i wypuszcza odnogi do bocznych celów.","The central splitter can work from opposite sides. Route red around a loop that feeds back into it and branches toward the side receivers."]],
  ["mcy1rx",["Zachowaj trzy składowe bieli do splątywacza przy górze. Pryzmat i Doppler pomogą na drugiej części drogi wytworzyć pary kolorów potrzebne przy kanałach.","Keep all three white components until the upper tangler. The prism and Doppler can prepare the pairs needed near the conduits."]],
  ["pimv19",["Wyślij czerwony poziomo do zachodniego portalu. Po przeskoku zachowa kierunek, więc ustaw dalszy zakręt po wschodniej stronie.","Send red horizontally into the west portal. It keeps its direction through the jump, so plan the next turn on the east side."]],
  ["s5dcbp",["Doprowadź oba kolory do środkowego portalu z przeciwnych stron. Czerwony wyjdzie w lewo, a niebieski w prawo, gdzie mają własne cele.","Feed the centre portal from opposite sides. Red exits to the left and blue to the right, each toward its own receivers."]],
  ["1cmvafu",["Przy parach sąsiednich odbiorników wykorzystaj jeden odcinek dla obu. Portal przy górze może skierować niebieski w lewo, a zachodnia trasa zabierze zielony niżej.","Use one beam stretch for each neighbouring receiver pair. An upper portal can deliver blue leftward while green takes a western route farther down."]],
  ["39zvfx",["Zacznij od kontrolowania jednej składowej czerwonego obiegu. Zmiany w Dopplerze mają wprowadzić niebieski i zielony na fragmenty tej samej sieci zakrętów.","Establish one section of the red loop first. Doppler shifts introduce blue and green into stretches of the same network of bends."]],
  ["p9bzty",["Użyj pryzmatu do rozłożenia bieli, a niekolorowe cele potraktuj jak pola, których żadna z odnóg nie może dotknąć. Zielony ma wyjść na prawo.","Use the prism to spread white into its channels. Treat colourless receivers as places every branch must avoid. Green needs a rightward exit."]],
  ["igh3kq",["Tu liczą się tylko dwa czerwone cele, oba oświetlane wiązką biegnącą ukośnie w górę i w prawo. Zacznij od znalezienia dwóch takich dojść omijających ciemne pola.","Only two receivers require red, and both accept an up-right ray. Find two diagonal approaches that avoid every dark receiver."]],
  ["m97zj2",["Niebieski przez portal dotrze na dół bez przecinania ciemnych celów. Dalej rozdziel go na lewy i prawy tor, pilnując bocznych dojść.","Use the portal to bring blue down without crossing dark receivers. Then use the lower splitters to route it left and right."]],
  ["1rfiha5",["Rozdziel zadanie według barw. Czerwoną i zieloną trasę złam po skosie przed grupą ciemnych celów, żeby nie przebijały się przez środek.","Plan red and green separately. Turn both onto diagonals before the dark receivers so their routes avoid the centre."]],
  ["cs4bpf",["Z czerwonego źródła potrzebujesz trzech barw. Jedną odnogę zamień w zieloną wcześniej, a splątaną trasę i portal wykorzystaj do dostarczenia niebieskiego do górnych celów.","Build all three colours from the red source. Shift one branch to green early, and use the entangled route and portals to get blue to the upper receivers."]],
  ["1h32xm6",["Użyj kanałów jako wskazówek kierunku. Niebieski może wejść do górnej części po przekątnej, a zielony zachowaj na pionowych odcinkach przez wspólne elementy.","Use the conduit axes as compass marks. Blue can reach the upper area diagonally, while green follows vertical stretches through shared optics."]],
  ["jpqpgt",["Zacznij od celów mieszanych. Zaplanuj dojścia dwóch składowych do każdego z nich, a przez biały cel poprowadź przecięcie wszystkich trzech wiązek.","Start from the mixed receivers. Work out which bends will deliver the required pair of components to each before tracing the longer routes."]],
  ["1bz0805",["Górne portale mogą przekazać zielony w lewo, ale biały też potrzebuje własnego przejścia. Najpierw zaplanuj wyjścia, a potem doprowadź do nich właściwe kierunki.","The upper portals can carry green left, while white also needs its own jump. Plan the exits first and align the entrances to match."]],
  ["s3m4z9",["Rozprowadź biel do lewego celu, zanim pryzmat rozłoży widmo. Prawy biały cel zasili osobne zbieganie czerwieni, zieleni i niebieskiego.","Send white through the left receiver before splitting the spectrum. Rebuild white at the right receiver by bringing red, green and blue together."]],
  ["1hwtfjv",["Zacznij od dwóch wyjść czerwonej wiązki ze splątywacza. Po stronie dolnej Dopplery dostarczą zielony i niebieski, a para portali pomoże wrócić niebieskim torem ku górze.","Start with the tangler's two red branches. Lower Dopplers supply green and blue, and a pair of portals helps take blue back into the upper area."]],
  ["1tosbf2",["Wykorzystaj zakrzywiacze jako zakręty między odcinkami o różnych barwach. Najważniejszy wzorzec to Doppler przed rozstajem: kolor na jego wyjściu trzeba dobrać do dalszych celów.","Use the benders to link the differently coloured stretches. Get each Doppler's output right before committing to the branch that serves the next receivers."]],
 ])],
 [2,new Map([
  ["1jkapxx",["Z niebieskiego pionu zrób główny pień. Rozdzielacze zabrane na dalszy etap mogą zasilać cele stojące w całych rzędach.","Use the vertical blue beam as a trunk. Branch from it with splitters where a single branch can feed a whole row."]],
  ["io01hn",["Szukaj przekątnych, które zmieniają stronę korytarza. Zakrzywiacz może wrócić do pionu tam, gdzie zwykły lustrzany skręt rozminąłby się z przejściem.","Look for diagonals that cross the corridor. Benders can recover the vertical where a mirror would miss the opening."]],
  ["1pxp4nz",["Odbij biel z prawej z powrotem w lewo. Rozdzielacze na wspólnej osi obsłużą odnogi w górę i w dół zależnie od kierunku wejścia.","Send white back from right to left. The splitters on the shared axis can branch up or down depending on the input direction."]],
  ["h2h5v4",["Zacznij od źródeł skierowanych na zewnątrz. Zewnętrzne zakręty mają posłać odnogi czerwieni i zieleni na różne przekątne, zanim te wrócą między cele.","Start with the outward-facing emitters. Use the outer turns to put red and green onto separate diagonals before they return toward the receivers."]],
  ["je679c",["Doprowadź biel do splątywacza po wcześniejszym zakręcie. Na dolnej odnodze czerwony filtr wyodrębni składową, którą Doppler może zmienić na zieloną.","Turn white into the tangler. The red filter on the lower branch isolates the component that the Doppler can turn green."]],
  ["1rmozey",["Znajdź pionowy łańcuch kanałów prowadzący do czerwonego odbiornika od dołu. Długi objazd czerwieni pozwoli wejść w tę oś i ominąć ciemny cel.","Find the vertical conduit chain into the red receiver from below. A long red detour approaches that axis while avoiding the dark receiver."]],
  ["19opru",["Wielofiltr powinien dostać biel z lewej i od dołu. Kąt jednego wejścia da czerwień, a drugiego niebieski, zanim rozdzielisz kierunki.","Feed the multifilter white from the left and below. The two entry angles select red and blue before their final turns."]],
  ["ewqe3n",["Złam dolną białą wiązkę na przekątną przed wielofiltrem. Pozwoli to wyciągnąć niebieski pod innym kątem niż zielony z poziomej wiązki.","Bend the lower white beam onto a diagonal before the multifilter. That entry selects blue while the horizontal input selects green."]],
  ["sup3az",["Trzy kolory spotykają się przy jednym wielofiltrze. Zaplanuj wejścia tak, żeby odpowiednia odnoga przeszła dalej, a ciemne pola pozostały bez światła.","Three colours meet at one multifilter. Arrange their entry angles to pass the useful branch and leave the dark receivers unlit."]],
  ["19mfzr7",["Jedno wejście do skrętnika można wykorzystać do określenia pozostałych. Prześledź pionowy niebieski tor aż do skrętu o ćwierć obrotu, potem zastosuj go do ukośnej bieli.","Use one twister input to reason about the rest. Track the vertical blue beam through its quarter-turn, then apply that turn to diagonal white."]],
  ["ztvovd",["Potraktuj dwa skrętniki jako węzły powracających zielonych dróg. Buduj odcinki między nimi, wykorzystując każdy przelot do zasilenia celów po drodze.","Treat the twisters as nodes in returning green routes. Build the stretches between them and light receivers along each pass."]],
  ["16tv0bo",["Środkowy rozdzielacz będzie bardziej użyteczny, gdy dostanie niebieski z obu stron. Zaplanuj powrót jednej gałęzi, żeby uzyskać pionowe dojścia.","The central splitter is more useful when fed from both sides. Route one branch back so it can supply the vertical runs."]],
  ["7q11z9",["Ustaw kąty wejścia bieli do wielofiltra z myślą o wszystkich trzech składowych. Dalsze zakręty dobieraj po kolorze, szczególnie przy żółtym i magencie.","Set up white inputs at different multifilter angles to extract all three channels. Route the outputs by colour, especially toward yellow and magenta."]],
  ["12pce3y",["Zielony ma zawracać do centralnego skrętnika. Po pierwszej zmianie osi użyj luster na wschodzie i południu do zbudowania powrotu.","Green needs to return to the central twister. After the first turn, use mirrors on the east and south to create that return."]],
  ["kwfwhp",["Niebieski ma przejść przez dwa niezależne skoki. Między nimi użyj skrętnika, żeby zamienić pionową podróż portalu na poziomą.","Blue needs two separate portal jumps. Use the twister between them to change from vertical travel to horizontal."]],
  ["1gkld8i",["Wyznacz dwa dłuższe zielone odcinki przez środkowe przejścia. Zakrzywiacze pozwalają obsłużyć wschodni cel po przekątnej, zostawiając miejsce na powrót lewą stroną.","Find two long green runs through the central passages. Benders can reach the eastern receiver diagonally and leave room for the west-side return."]],
  ["eyjjk3",["Pryzmat dostarczy osobne składowe do kanałów. W górnym przejściu pilnuj niebieskiego wejścia do Dopplera, bo dalszy odcinek wymaga czerwieni.","Use the prism to feed separate components into the conduits. At the upper crossing, the Doppler takes blue so the next run can carry red."]],
  ["1trkr3w",["Pierwszą czerwoną drogą zasil komplementor. Na jednym wyjściu otrzymasz cyjan; filtr pozwoli wydobyć z niego zielony i uruchomić kolejną przemianę.","Feed the complementor with the first red route. It gives cyan, from which a filter can extract green to trigger the next conversion."]],
  ["1i9z513",["Użyj rozdzielacza, żeby doprowadzić obie źródłowe barwy w okolice prawego komplementora. W jednym wejściu czerwony i zielony razem pozwolą uzyskać niebieski.","Use the splitter to bring both source colours toward the right complementor. At one input, red and green together can produce blue."]],
  ["xlpr3y",["Podaj niebieski i zielony do komplementora pod różnymi kątami. Żółta i purpurowa odnoga potrzebują osobnych wyjść, a cel cyjanowy korzysta z dwóch źródeł.","Feed blue and green into the complementor at different angles. Yellow and magenta need separate outputs, while cyan uses the two source channels."]],
  ["174z8eh",["Twórz żółty przy samych celach, rozprowadzając czerwony i zielony osobnymi liniami. Rozdzielacze pozwolą każdej składowej obsłużyć kilka przecięć.","Build yellow at the receivers by carrying red and green on separate lines. Use splitters to let each channel serve several crossings."]],
  ["1lg23ay",["Wydziel czerwone odnogi od splątywacza, zanim zaczniesz rozprowadzać niebieski. Skrętniki w środku potrafią przekierować kilka wejść naraz.","Set up the red branches from the tangler before routing blue. The central twisters can redirect several input beams at once."]],
  ["pi3lsg",["Doprowadź białą wiązkę do wielofiltra z kilku kierunków dzięki rozdzielaczom. Jeden element da trzy różne barwy, jeśli ich kąty wejścia się różnią.","Use splitters to feed white into the multifilter from several directions. One device yields three colours if the inputs have different angles."]],
  ["1m4kw1r",["Niebieski opanuj najpierw w górnym rzędzie. Wspólny rozdzielacz może tam przyjąć niebieski z dołu i zielony po skosie, bez mieszania ich dalszych tras.","Establish blue in the upper row first. A shared splitter can receive blue from below and green diagonally while keeping their routes separate."]],
  ["1c3zt63",["Poprowadź czerwony w dłuższy obieg. Środkowe skrętniki przerzucają go między przekątnymi i pozwalają ponownie wykorzystać wcześniejsze zakręty.","Build a long red loop. The central twisters move red between diagonals and let the route reuse earlier bends."]],
  ["x2b2x1",["Zielony i magenta składają się na biel. Wytwórz magentę w komplementorze i zawróć ją do białego celu, zachowując osobną zieloną odnogę.","Green plus magenta makes white. Produce magenta at the complementor and loop it toward the white receiver while preserving a green branch."]],
  ["1wgzh2u",["Potraktuj komplementor jak skrzyżowanie. Od czerwieni uzyskasz cyjan na jednej osi, od zieleni magentę na drugiej; skrętniki rozprowadzają je do par celów.","Treat the complementor as a junction. One axis turns red into cyan, another turns green into magenta, and the twisters distribute them to pairs of receivers."]],
  ["84jljc",["Obejdź gęstą zabudowę od dołu. Najpierw znajdź dwa ukośne odcinki wychodzące z dolnych zakrzywiaczy, zanim spróbujesz zasilić górę.","Loop around the dense walls from below. Work out the two diagonal stretches leaving the lower benders before attempting the upper receivers."]],
  ["wnlv5b",["Niebieskie źródło najpierw zamień w żółte światło. Odfiltruj z żółtego czerwień i skieruj ją ponownie do komplementora, żeby uzyskać cyjan.","Complement blue to yellow first. Filter red out of yellow and send the red back into the complementor to get cyan."]],
  ["1doqhs4",["Zachowaj bezpośrednie trafienia z zewnętrznych laserów. Wielofiltr wykorzystaj na przecięciach, gdzie trzeba zatrzymać wiązkę przed ciemnym rezonatorem.","Preserve the direct hits from the outer lasers. Use multifilters at crossings where a beam would otherwise reach a dark receiver."]],
  ["gjlwv7",["Skrętnik w środku obsługuje kilka kierunków równocześnie. Ustaw wejścia czerwieni i zieleni tak, żeby mogły dołączyć do innych składowych dopiero przy mieszanych celach.","The central twister serves several directions at once. Route red and green so they combine with the other channels only at the mixed receivers."]],
  ["1kjru6s",["Niebieski w komplementorze da żółty, zielony da magentę. Zacznij od tych dwóch przemian i przepleć ich wyniki z barwami źródłowymi.","The complementor turns blue into yellow and green into magenta. Start with those conversions, then interleave their output paths with the source colours."]],
  ["kvueee",["Biel do wielofiltra może wracać po różnych przekątnych. Ustaw pierwszy skrętnik tak, aby ten sam filtr miał wejścia dające czerwony, zielony i niebieski.","White can return to the multifilter along different diagonals. Set the first twister so one filter gets the inputs needed to select red, green and blue."]],
  ["pl1t12",["Rozdziel czerwień na parę i śledź jej strony osobno. Łańcuch Dopplerów ma kolejno zasilać zielone, czerwone i niebieskie cele, często po obu stronach planszy.","Split red into a pair and track both partners. The Doppler chain has to keep producing green, red and blue for groups on opposite sides."]],
  ["14au6af",["Zaplanuj fragment czerwonej pętli z dwóch końców. Skrętniki przy środku wysyłają podobne wejścia w różne strony po stałym obrocie o 90°.","Plan part of the red loop from both ends. The central twisters send nearby input directions onto different paths by applying the same 90-degree turn."]],
  ["1burvnn",["Pierwsze lustra przeprowadzą czerwień przez górę. Po prawej rezerwuj zakrzywiacze na przejście z pionu na przekątną i na powrót dolną krawędzią.","Use the first mirrors to take red across the top. Save right-side benders for changing vertical to diagonal and bringing red back along the bottom."]],
  ["1v6jfw7",["Żółty wymaga zbiegu zieleni z czerwienią. Osobne wejścia do komplementora dostarczą magentę i cyjan, więc nie miksuj jego wejść przedwcześnie.","Yellow needs green and red to meet. Keep the complementor inputs separate to get distinct magenta and cyan outputs."]],
  ["1fert6o",["Skrętnik ma dwie funkcje naraz: zielony skręca w lewo, niebieski w prawo. Dopasuj do tych wyjść niezależne trasy wokół ścian.","Make the twister send green left and blue right in the same setup. Route the two exits independently around the walls."]],
  ["nnicls",["Z jednego czerwonego źródła zasil oba wejścia do komplementora różnymi kolorami. Splątywacz i Doppler pomogą przygotować zielony i niebieski dla żółci i magenty.","Get two different colours into the complementor from one red source. The tangler and Doppler help supply the green and blue needed to make magenta and yellow."]],
  ["dneq8h",["Niebieski wytwarza żółty w komplementorze. Potem pryzmat rozłoży żółty na czerwony i zielony, których tory można skrzyżować u góry.","Use the complementor to turn blue into yellow. Split yellow with the prism so red and green can meet again at the upper receiver."]],
  ["16xq99y",["Trzy źródła idą w górę. Poszukaj takich zakrzywiaczy przy górnej krawędzi, które wyginają trzy osobne kolory w odcinki powrotne.","The three emitters all point up. Find upper-edge benders that can return all three colours along parallel routes without mixing them."]],
  ["1afrgk2",["Splątaj czerwony na pionową parę. Dolną drogę przekształć tak, aby zasiliła niebieski cel i wprowadziła zielony z powrotem do skrętnika.","Make a vertical red pair at the tangler. Transform the lower route so it can reach blue and feed green back to the twister."]],
  ["1r2xfyj",["Nie próbuj przejść czerwoną wiązką przez środek zabudowy. Ułóż długie ukośne odcinki od bocznych celów i sprawdź, gdzie łączą się w ciągły tor.","Work backward along the long diagonals from the side receivers. Look for places to join them into one red path around the walls."]],
  ["octbp5",["Pryzmaty mają zwrócić składowe na różne przekątne. Najpierw zbuduj parę dla jednego żółtego celu, a potem poprowadź niebieskie odnogi do cyjanu i magenty.","Use the prisms to set the component directions. Build one yellow pair first, then route the blue branches to cyan and magenta."]],
  ["1ezbdne",["Z czerwieni zrób niebieski, zanim rozdzielisz zadania górnej części. Wielofiltr na dole może zamknąć niechciane dojście do ciemnego celu.","Make blue from red before building the upper paths. A lower multifilter can shut off an approach to the dark receiver."]],
  ["1lzmn14",["Niebieski może stać się żółty w komplementorze i rozdzielić się w splątywaczu. Wykorzystaj te pary do wyprodukowania zieleni i dodatkowego niebieskiego przy górnych celach.","Turn blue into yellow at the complementor, then feed the tangler. Use the resulting pairs to create green and extra blue for the upper receivers."]],
  ["vl6p3k",["Traktuj środkowe skrzyżowania jak część pętli. Rozdzielacz z kilku wejść tworzy odnogi na różne przekątne, które zakrzywiacze kierują do narożników.","Treat the central crossings as parts of a loop. The splitter branches several inputs onto diagonals, and the benders carry them to the corners."]],
  ["1w3f90l",["Najpierw określ osie górnych kanałów. Zbuduj przejścia dla niebieskiego, a Dopplery dodaj tam, gdzie na tej samej trasie potrzebujesz czerwieni lub zieleni.","Work from the axes of the upper conduits. Route blue first, then place Dopplers where the same path needs to carry red or green."]],
  ["1ltm0gz",["Doprowadź po jednym kolorze do środka z trzech stron. Komplementor może działać jak miejsce wygaszenia krzyżujących się wiązek bez oświetlania ciemnych celów.","Bring one colour in from each of three sides. Use the complementor to stop the crossing beams before they reach the dark receivers."]],
  ["16tr6qm",["Najpierw rozwiąż górną parę portali, pilnując ciemnych pól. Zielony może wielokrotnie przecinać środkową część, ale czerwony i niebieski trzeba prowadzić własnymi rzędami.","Start with the upper portal pair and check the dark cells. Green can cross the middle repeatedly, while red and blue need separate rows."]],
 ])],
 [3,new Map([
  ["49rnxo",["Niebieski ma najpierw odbić od dołu planszy. Rozdziel go po powrocie na północny skos, żeby objąć cele stojące w dwóch ukośnych ciągach.","Bounce blue back from the bottom, then split it on the upward diagonal to serve the receivers along two lines."]],
  ["7zek65",["Masz cele w czterech częściach planszy. Zacznij od zakrętów w górnych narożnikach, które wypuszczają czerwony w dół do kolejnych części obiegu.","There are receivers in all four quarters. Work out the upper corner benders that send red down to the next sections of the loop."]],
  ["12gsh7v",["Wąskie korytarze zmuszają zielony do opuszczenia dolnego rzędu. Ostatni odcinek musi iść prosto w prawo, więc planuj wyjście z labiryntu od strony celu.","The narrow passages force green out of the bottom row. The last segment goes right, so work backward from the receiver to the maze exit."]],
  ["16bbr2r",["Rozdzielaj zieloną przekątną jeszcze w lewej części i ponownie niżej. Każda zachowana odnoga może zasilić kolejny rozdzielacz, zanim promień dotrze do prawej strony.","Split the green diagonal on the left and again farther down. Keep a branch to feed the next splitter before it reaches the right."]],
  ["14h7u13",["Środkowe odbiorniki można mijać wielokrotnie. Zacznij od długiego czerwonego odcinka w prawo, po którym zakrzywiacz daje ukośny powrót do środka.","Several runs can pass through the middle receivers. Start with a long red run to the right, then bend it diagonally back toward the centre."]],
  ["lup4u2",["W narożnikach jeden zakrzywiacz prowadzi obie barwy, jeśli dotrą z różnych kierunków. Zobacz, czy para tras może przechodzić przez te same zakręty bez mieszania.","A corner bender can turn both colours if they enter from different directions. Look for shared turns that keep the routes separate."]],
  ["cnglzs",["Pomyśl o magencie jako o skrzyżowaniu czerwonej i niebieskiej przekątnej. Dopiero po zaplanowaniu dojść do tych skrzyżowań prowadź osobne cele podstawowych barw.","Treat each magenta receiver as a red-blue diagonal crossing. Plan those approaches before routing the single-colour receivers."]],
  ["m9h5gw",["Niebieski potrzebuje pionowych dojść i ukośnych wyjść. W ciasnej środkowej części zakrzywiacze pomogą przejść między nimi bez wyjścia poza korytarz.","Blue needs vertical approaches and diagonal exits. Use benders to make those changes inside the narrow central passages."]],
  ["10hy966",["Rozdziel biel po lewej, ale przygotuj drugi pryzmat po prawej. Może przyjąć już rozdzielone barwy i na nowo ustawić ich kierunki.","Split white on the left, then prepare the second prism on the right. It can take already separated channels and set their new headings."]],
  ["akhrof",["Laser zaczyna w dół; odwróć trasę zakrzywiaczem, aby ruszyła ukośnie w górę i w lewo. Dalej prowadź ją po długich przekątnych między celami.","The emitter starts downward. Use a bender to send it up-left, then route it along long diagonals between the receivers."]],
  ["1358k8h",["Niebieski ostatecznie wchodzi w górny cel po skosie ku lewej. Zielony kończy ku prawej i w dół. Wyznacz te dwa dojścia przed układaniem objazdów przez środek.","The upper blue receiver is approached up-left, and green finishes down-right. Work backward along those two lines before building the central detours."]],
  ["1u4r2uc",["Biały środkowy cel wymaga wszystkich trzech źródeł. Zacznij od pionowego niebieskiego dojścia, a pozostałe dwa kolory doprowadź do niego po przekątnych.","The central white receiver needs all three emitters. Start with the vertical blue arrival, then bring in red and green on diagonals."]],
  ["12ggopl",["Najpierw wyślij biel ze środka planszy ukośnie do pryzmatu. Z jego wyjść zielony rusza w górę, czerwony po przekątnej, a niebieski wraca ku lewej stronie.","Bend white diagonally into the prism. Green leaves upwards, red takes a diagonal, and blue returns toward the left."]],
  ["ra9btw",["Zielony ma przejść przez skupiska celów w poziomie na środku i w pionie przy prawej stronie. Ułóż te proste odcinki, zanim połączysz je zakrzywiaczami.","Green passes receivers horizontally through the centre and vertically on the right. Plan those long runs before linking them with benders."]],
  ["jxgcij",["Rozpocznij od zakrętu w dół po lewej. Czerwony tor będzie ponownie przekraczał planszę, więc odszukaj późniejszy powrót z prawej przez wolny dolny odcinek.","Start with a downward turn on the left. Red crosses the board again later, so look for a lower return from the right."]],
  ["1wgzfeh",["Szukaj w labiryncie par prostych korytarzy pod kątem 90°. W tej zagadce niebieski może zmieniać kierunek zwykłymi lustrami; szczególnie wykorzystaj długie odcinki przy krawędziach.","Look for right-angle corridor pairs. Ordinary mirrors can turn blue here, and the long lanes along the edges are useful."]],
  ["ac5fte",["Doprowadź poziomy czerwony i niebieski do dwóch stron wspólnego lustra. Czerwony wyjdzie w górę, niebieski w dół.","Bring horizontal red and blue to opposite faces of the shared reflector. Red turns upward and blue turns downward."]],
  ["mpjh27",["Środkowe dwustronne lustro rozsyła czerwony w górę, niebieski w dół. Dopiero za nim użyj rozdzielaczy do obsłużenia ciasnych bocznych korytarzy.","The central dual reflector sends red up and blue down. Use the splitters after it to serve the narrow side corridors."]],
  ["manzof",["Każdy rząd białych laserów ma dojście do górnego kanału. Szukaj otwartych osi kanałów i buduj kolejne trasy oddzielnie, odbijając biel z rzędu ku górze.","Each row of white emitters can reach an upper conduit. Work through the rows separately and reflect white upward into the open conduit axes."]],
  ["164qunk",["Zostaw biel w całości. Na zakrętach wykorzystuj to, że ten sam zakrzywiacz może skierować wiązkę w inne miejsce przy powrocie z innej strony.","Keep white intact. A bender can send the same light somewhere new when the beam returns from a different direction."]],
  ["1rajw35",["Do jednego niebieskiego celu dojście biegnie prosto w górę, do drugiego ukośnie w dół w prawo. W wąskim korytarzu planuj te odcinki z wyprzedzeniem.","One blue receiver is approached straight up and another down-right. Plan those approach segments before working through the tight passages."]],
  ["6wykae",["Cztery kolory powinny spotkać się na czterech stronach poczwórnego zakrzywiacza. Lustra najpierw ustawiają ich wejścia na osiach; wyjścia idą po przekątnych ku celom.","Bring the four colours to the four sides of the quad bender. Use mirrors to establish straight inputs, then take the diagonal exits to the receivers."]],
  ["u89n81",["Wspólny poczwórny zakrzywiacz zamienia cztery osiowe wejścia w cztery przekątne. Dopiero po tym rozdziale dobieraj zbiegi dla żółtego i cyjanu.","A shared quad bender turns four straight inputs onto four diagonals. Set up the later crossings for yellow and cyan after that junction."]],
  ["9mjkso",["Czerwony trafia do poczwórnego zakrzywiacza po przekątnej z centrum. Spróbuj sprowadzić pozostałe wejścia również po przekątnych, żeby wyjścia wróciły do osi.","Red enters the quad bender diagonally from the centre. Bring the other inputs in diagonally too so the exits line up with rows and columns."]],
  ["15dz7k",["Rozdziel zadanie według połówek planszy. Błękit potrzebuje ukośnych dojść w górnej części, zielony prostego odcinka w prawo i skosu na dole.","Split the task into upper and lower halves. Blue needs diagonal arrivals above, while green needs a rightward line and a lower diagonal."]],
  ["1ez2j6x",["Z zielonego pionu łatwiej zbudować boczne odcinki niż trafić od razu do górnych celów. Zarezerwuj górę na długie przejścia w lewo.","Use the vertical green beam to establish side routes before tackling the upper receivers. Save room above for long leftward runs."]],
  ["1y3w385",["Pierwszy poziomy niebieski przelot poprowadź do zachodnich zakrętów. Zakrzywiacze przerzucą go między osiami i przekątnymi w kilku sąsiednich korytarzach.","Take the initial horizontal blue run toward the western turns. Benders switch between straight and diagonal paths in the neighbouring corridors."]],
  ["17g9qnm",["Zacznij od białego celu po prawej. Zarezerwuj dla niego trzy dojścia, a magentę i cyjan zbuduj na innych przecięciach tych tras.","Start with the white receiver on the right and reserve three approaches. Build magenta and cyan at other crossings of those paths."]],
  ["1r95sg4",["Wiele niebieskich celów u góry znajduje się na wspólnych prostych. Buduj długie odcinki w prawo i wracaj od nich ukośnie ku lewej.","Several upper blue receivers share straight lines. Build long runs to the right and route their returns diagonally left."]],
  ["1v2gqpj",["Do dwóch czerwonych celów przy górze dochodzi się z różnych kierunków. Zlokalizuj wąskie przejścia z lewej, które pozwolą jedną trasę doprowadzić w pion, a drugą ukośnie.","The upper red receivers have different approaches. Find the tight left openings that allow one vertical and one diagonal arrival."]],
  ["6rpbrk",["Przy zwykłych lustrach szukaj długich odcinków poziomych i pionowych. Górne cele potrzebują serii prawych odcinków, a dolne dostaną powroty w lewo.","Use long horizontal and vertical runs between mirrors. The upper receivers need rightward stretches, and the lower ones can use leftward returns."]],
  ["b5umje",["Zachowaj białe widmo i poprowadź wiązkę między bocznymi zakrzywiaczami. Jeden z nich może zmienić południową przekątną w długi odcinek przez środek.","Keep white intact and route it between the side benders. One turns a downward diagonal into a long stretch through the centre."]],
  ["15fm0ib",["Dwustronne lustro po lewej wymienia kierunki poziomy i pionowy dla czerwonych powrotów. Ustaw jego dwa wejścia, a dopiero potem buduj pozostałe pętle.","The left dual reflector swaps horizontal and vertical headings for the red returns. Establish its two approaches before building the other loops."]],
  ["sei852",["Magenta w środku potrzebuje niebieskiego po skosie i czerwonego od dołu. Zostaw te dwie odnogi otwarte podczas prowadzenia reszty celów po bokach.","The central magenta receiver needs diagonal blue and upward red. Keep those arrivals open while routing the other colours along the sides."]],
  ["13g64qh",["Rozdzielacz w środku pracuje na kilku zielonych wejściach. Poprowadź powroty tak, żeby tworzył nowe przekątne przy kolejnych przejściach.","The central splitter handles multiple green inputs. Set up the returns so later passes generate fresh diagonals."]],
  ["ncyilh",["Zbuduj czerwony tor w górnej części i niebieski powrót przez dół. Przy magencie zaplanuj spotkanie czerwonej przekątnej z niebieskim pionem.","Establish the upper red route and the lower blue return. At magenta, plan for a red diagonal to cross a vertical blue run."]],
  ["165axlf",["Dwustronne lustro działa na osiach obu torów. Ustaw najpierw jego niebieskie wejście z dołu, potem skieruj zielony poziomo z boku.","The dual reflector serves the axes of both paths. Establish its blue input from below, then feed green horizontally from a side."]],
  ["cyfgh5",["Doprowadź czerwony w górę do długiego rzędu celów. Zakrzywiacze po prawej pozwolą z niego zawrócić na skos z powrotem przez środek.","Bring red up to the long upper row of receivers. Right-side benders can then send a diagonal return through the centre."]],
  ["nmknou",["Środkowe dwustronne lustro przyjmuje kilka czerwonych i zielonych przekątnych. Najpierw sprawdź, jak odbija jedną parę, żeby pozostałe pętle wykorzystały ten sam obrót.","The central dual reflector handles multiple red and green diagonals. Work out one pair of reflections so the remaining loops can use the same orientation."]],
  ["ymurw4",["Przeprowadź zielony przez rząd u góry, a niebieski odwróć z prawej w dół. Następne lustra utworzą odcinki powrotne w dolnej połowie.","Take green along an upper row and turn blue down on the right. Later mirrors create the return runs in the lower half."]],
  ["1nqb31i",["Dwa żółte odbiorniki przy środku potrzebują osobnych przecięć czerwieni z zielenią. Niebieski ma pojedyncze zadanie: poprowadź go po skosie do środka.","The two central yellow receivers need separate red-green crossings. Blue has one job: reach the centre on a diagonal."]],
  ["1kyvemd",["Cyjan przy obu narożnikach składa się z niebieskiego i zielonego, ale każdy powstaje z innych kierunków. Ustaw odbicia wokół ścian, pilnując osobnych wejść.","Both corner cyan receivers need blue and green, but from different directions. Route their reflections around the walls and keep the approaches separate."]],
  ["1t7ygtv",["Rozdziel cele według źródeł. Biały zostaje przy lewej górze, a czerwony i zielony wymagają osobnego przejścia przez dolną połowę planszy.","Group the receivers by source. White stays near the upper left, while red and green each need a route through the lower half."]],
  ["1xncp5",["Obsłuż cztery cyjanowe narożniki, rozdzielając każdą parę niebieskiej i zielonej trasy. Do mieszania może dojść dopiero przy celu, podczas ukośnych dojść.","Serve the four cyan corners by routing separate blue and green paths. Let them combine only at the receivers on their diagonal approaches."]],
  ["25lsff",["Górny biały cel wymaga dołożenia źródłowych barw z trzech kierunków. Dolny biały tor wygnij po lewej, zanim zaczniesz przeprowadzać zielony pomiędzy nim a celami.","The upper white receiver needs the primary colours from three directions. Bend the lower white path on the left before routing green across it."]],
  ["1s6lhs",["Kolejne zakrzywiacze po prawej przenoszą czerwień w dół i z powrotem przez środek. Zacznij od jednego odcinka, który zasila kilka celów w tym samym rzędzie.","Right-side benders take red down and back across the middle. Begin with a run that serves several receivers in one row."]],
  ["keisls",["Dwa żółte cele buduj z czerwieni i zieleni, każdy z innym wejściem. Biały u góry poprowadź własną drogą omijając ciemny cel po prawej.","Build the two yellow receivers from red and green with different approaches. Route upper white independently and keep it off the dark receiver on the right."]],
  ["m3bu63",["Poprowadź trzy źródła wzdłuż równoległych tras. Przy powrocie niektóre lustra mogą obsłużyć dwa kolory jednocześnie, jeśli oba biegną w pożądanym kierunku.","Build parallel routes for the three emitters. Some return mirrors can carry two colours at once when both need the same turn."]],
  ["89y22c",["Poczwórny zakrzywiacz w środku pozwala przełożyć kilka zielonych wejść na nowe osie. Najpierw znajdź drogę powrotną do niego z górnej części.","The central quad bender gives several green inputs new headings. Find a return to it from the upper area before routing more branches."]],
  ["hayonx",["Zielony i niebieski obsługują rozległe sieci. Czerwony ma mniej celów, więc najpierw doprowadź go po prawej do środka i zarezerwuj jego ostatnie przekątne.","Green and blue cover sprawling networks. Red has fewer receivers, so route it in from the right first and reserve its finishing diagonals."]],
 ])],
 [4,new Map([
  ["6nduwf",["Czerwony i niebieski w wąskim korytarzu mogą przechodzić przez te same przyrządy. Wykorzystaj pryzmat do rozdzielenia kierunków, zanim dotrą do dolnych celów.","Red and blue can share devices inside the narrow passage. Use the prism to separate their headings before they reach the lower receivers."]],
  ["jc8d76",["Niebieski i zielony wracają do poczwórnego zakrzywiacza z różnych kątów. Ustaw jego zielone wejście od dołu, potem dobierz niebieski powrót.","Blue and green return to the quad bender from different angles. Establish its green input from below, then arrange the blue return."]],
  ["bj2r6k",["Z czerwieni potrzebujesz także zieleni i niebieskiego. Splątywacz daje dwa kierunki; obserwuj obie odnogi naraz, gdy Doppler dotknie jednej.","Red must also produce green and blue. The tangler gives you two directions. Watch both branches when the Doppler touches one of them."]],
  ["3u0cs",["Dwie zielone wiązki spotkają się na bramce pod symetrycznymi kątami. Odbij każdą od górnej części do środka, żeby bramka mogła wysłać wspólny sygnał w dół.","The logic gate needs green on two symmetrical inputs. Reflect each beam inward from the upper receivers so the gate can send their shared signal down."]],
  ["d4vc3j",["Zacznij od wejść bocznych bramek. Ich wyjścia podążają ukośnie ku sobie i razem mogą uruchomić bramkę kierującą czerwień w górę.","Start with the side gates. Their outputs head diagonally toward one another and can activate the gate that sends red upward."]],
  ["1voosmw",["Bramka przepuści wspólną czerwień z dwóch ukośnych wejść. Zielone i niebieskie składowe mają osobne zadanie przy żółtym i magencie.","The logic gate extracts the red shared by its diagonal inputs. Green and blue are needed separately for the yellow and magenta receivers."]],
  ["3lnxj1",["Wyznacz odcinki dla czterech kolorów mieszanych. Rozdzielacze rozprowadzą poszczególne składowe, a filtry przy środku pomogą odseparować te, które zakłócają cel.","Plan the arrivals for all four mixed colours. Use splitters to distribute the components and filters to isolate those that would spoil a receiver."]],
  ["dngo9y",["Poszukaj zielonego odcinka w prawo, który oświetla cały rząd. Wyrób z niego przekątny powrót, aby ten schemat wykorzystać na dalszych rzędach.","Find a rightward green stretch that lights a row. Add a diagonal return so similar runs can serve the other rows."]],
  ["1rs119g",["Gwiazdorozdzielacz potrzebuje czerwonego i zielonego wejścia. Gdy trafisz do niego i osiowo, i po skosie, oba kanały dotrą do żółtych celów na różnych liniach.","Feed the starburst red and green. Straight and diagonal inputs let both channels reach yellow receivers on different lines."]],
  ["1w11e6r",["Najpierw doprowadź czerwony pion do gwiazdorozdzielacza. Cztery przekątne dadzą punkty zaczepienia dla narożnych celów; niebieski poprowadź odrębną trasą.","Feed vertical red into the starburst first. Its four diagonals give you routes toward the corners. Route blue separately."]],
  ["1i3mjb2",["Zacznij przy niebieskim odbiorniku, odczytując kąt najbliższego kanału. Zakrzywiacze muszą kolejno łączyć osie kanałów z przekątnymi.","Start at the blue receiver and read the axis of the nearest conduit. Use benders to connect straight conduit axes to diagonal stretches."]],
  ["1i71m4u",["Podaj zieleń do gwiazdorozdzielacza od góry. Komplementor na odnogach może dać magentę, która po powrocie złoży się z zielenią na biel.","Feed the starburst green from above. Use the complementor on the branches to make magenta, then return it to combine with green as white."]],
  ["a4smzm",["Doprowadź parę niebieski–zielony do splątywacza. Jedna odnoga posłuży cyjanowi, a zmiany Dopplera i komplementora pozwolą zbudować pozostałe mieszanki.","Bring blue and green together at the tangler. One branch can serve cyan, while the Doppler and complementor changes help build the other mixtures."]],
  ["s1m334",["Ciemne cele wyznaczają miejsca, które trzeba ominąć. Skup się najpierw na poziomych dojściach do czerwonych celów, a lustra stawiaj tam, gdzie dwa takie odcinki da się połączyć pionem.","Dark receivers rule out certain lanes. Start with horizontal approaches to red, then find vertical runs that mirrors can use to join them."]],
  ["11sa8ck",["Komplementor może zmienić niebieski w żółty. Rozdziel żółtą trasę tak, by dostarczyć światło do żółtego celu i jednocześnie podać część sygnału na bramkę.","Use the complementor to turn blue into yellow. Split the yellow route so it can reach its receiver and also feed the gate."]],
  ["vjzqr4",["Splątywacz u góry daje parę powrotów ku bokom. Dopplery zmienią ich widmo, a gwiazdorozdzielacz rozprowadzi różne składowe po osiach i przekątnych.","The upper tangler gives you a pair of side returns. Shift their colours with Dopplers and use the starburst to spread channels along straight and diagonal lines."]],
  ["1vne0uz",["Nie rozkładaj bieli. Spróbuj przejść zakrzywiaczami z pionów na przekątne, a przy bokach załóż dłuższe odcinki w lewo i w prawo.","Keep white together. Use benders between vertical and diagonal stretches, then find long leftward and rightward runs along the sides."]],
  ["o21i38",["Splątaj czerwień wcześnie, żeby móc uzyskać niebieski i zielony. Pionowy niebieski wejdzie do jednego gwiazdorozdzielacza, zielona przekątna do drugiego.","Entangle red early to obtain blue and green. Feed one starburst vertical blue and the other diagonal green."]],
  ["1jlm5so",["Ustaw ruchome portale na wspólnej osi między ścianami. Czerwień i błękit mogą korzystać z tej samej linii skoku, przemieszczając się w przeciwnych kierunkach.","Align the movable portals on the same axis through the walls. Red and blue can share the jump while travelling in opposite directions."]],
  ["1xemd5l",["Ruchomy portal ratuje trasę, gdy po zakręcie kolejny rezonator leży za ścianą. Ustaw wyjście tak, aby zachować potrzebny kierunek przed następnym zakrzywiaczem.","Use a movable portal when the next receiver lies beyond a wall. Position the exit to keep the heading needed by the next bender."]],
  ["5d7993",["Zostaw bezpośrednie trafienia, które już są poprawne. Ruchome portale wykorzystaj przy mieszanych celach do nakładania składowych z poziomych i pionowych źródeł.","Keep the direct hits that already work. Use movable portals at mixed receivers to overlap channels from horizontal and vertical emitters."]],
  ["x9a2v0",["Zachowaj jedną splątaną odnogę dla bieli. Na drugiej wykorzystaj pryzmat i Doppler do uzyskania składowych potrzebnych przy zielonym i cyjanie.","Keep one entangled branch for white. Use the prism and Doppler on the other to build the components green and cyan require."]],
  ["8gb4cn",["Portale w środku przepuszczają czerwony i niebieski w przeciwnych kierunkach. Skrętniki przed i po skoku zamieniają ruch pionowy na poziomy lub odwrotnie.","The middle portals pass red and blue in opposite directions. Twisters before and after each jump change between horizontal and vertical travel."]],
  ["12ck782",["Zielona wiązka wraca kilka razy z nowych kierunków. Ruchome portale pomagają połączyć prawą dolną część z lewą, zanim zbudujesz odcinki ku górze.","Green returns from several directions. Movable portals can link the lower right with the left side before you build the upward stretches."]],
  ["1o9o43u",["Zielony i niebieski mogą się przecinać poza celami. Prowadź je dłuższymi bocznymi odcinkami i pilnuj, by żaden powrót nie trafił w cztery ciemne cele u góry.","Blue and green can cross away from the receivers. Use long side stretches and keep the return beams off the four dark receivers above."]],
  ["1lm8uow",["Przepuść białą trasę po skosie między ścianami, a zielony uzyskaj dopiero na pionowym odcinku przez filtr. Zajęte pole nadal przepuszcza wiązkę.","Route white diagonally through the walls, then use the filter on the vertical run to obtain green. Light can pass through the occupied square."]],
  ["1dwqi94",["Wykorzystaj kilka długich zielonych odcinków w obie strony przez górę. Środkowe zakrzywiacze mają sprowadzać wiązkę niżej lub odsyłać ją do góry pod nowym kątem.","Use long green runs in both directions across the upper area. Let central benders take green lower down or return it upward under a new heading."]],
  ["bxetgl",["Czerwony zasila dolne cele długimi odcinkami w prawo. Górne boki wykorzystaj do ukośnych powrotów, które ponownie wpuszczą czerwień między rzędy.","Long rightward red runs serve the lower receivers. Use the upper sides for diagonal returns that feed red back between the rows."]],
  ["ve5ij9",["Doppler może wytworzyć czerwień z niebieskiego po skosie. Potem gwiazdorozdzielacze rozprowadzają czerwone odnogi; zachowaj niebieski potrzebny magencie.","Use the Doppler to make red from diagonal blue. Spread red with starbursts and keep some blue for the magenta receiver."]],
  ["143ccc9",["Pierwszy rozrzut bieli dostarcza odnogi do osobnych filtrów. Po filtracji wprowadzaj pojedyncze kolory do kolejnych gwiazdorozdzielaczy, żeby oświetlić cele mieszane.","Fan white toward separate filters first. Feed the isolated channels into the later starbursts to reach the mixed receivers."]],
  ["13hdhdx",["Po wielofiltrze zbuduj niebieski odcinek w prawo. Zachowaj czerwone drogi dla celów po prawej, a Doppler zarezerwuj na zielone wyjście.","Build a rightward blue run after the multifilter. Keep red routes for the right-side receivers and reserve the Doppler for a green exit."]],
  ["m8raa4",["Zajęte pola przepuszczają światło, więc możesz liczyć przekątne przez nie. Ustaw lustra na wolnych polach, gdzie zmienia się kierunek, a ostatnie dojście poprowadź w górę i lewo.","Occupied cells transmit light. Count diagonals through them and place mirrors in the free cells where the path changes heading. Finish up-left."]],
  ["xf3ejn",["Użyj ruchomego portalu do przeniesienia czerwieni przez część z ciemnymi celami. Najpierw znajdź czerwony powrót w lewo, który da się wpuścić do pary portali.","Use a movable portal to take red across the region with dark receivers. Start by finding a leftward return that can enter a portal pair."]],
  ["6xz46y",["Gwiazdorozdzielacz u góry może jednocześnie dostać czerwony z osi i przekątnej. Skrętnik na dole przestawi powracające odnogi bez zmiany barwy.","The upper starburst can receive red on a straight line and a diagonal. The lower twister redirects returning branches without changing their colour."]],
  ["hl3llk",["Dwustronne lustro wymienia dwie niebieskie przekątne w środku. Po stronie dolnej wykorzystaj kolejno kanał i gwiazdorozdzielacze do rozprowadzenia odnóg.","The dual reflector swaps two blue diagonals in the middle. In the lower area, use the conduit and then the starbursts to distribute the branches."]],
  ["kxup13",["Górny zielony cel potrzebuje zachowania zieleni. Resztę zaplanuj według przekątnych czerwonych i niebieskich, które korzystają z różnych stron dwustronnego lustra.","Preserve green for the upper green receiver. Plan the rest around red and blue diagonals using different faces of the dual reflector."]],
  ["14fbxzw",["Pozwól czerwieni przejść prosto przez zajęte pola przy górze. Pierwszy zakręt wypada po tym przejściu; szukaj późniejszego poziomego odcinka przy dolnym celu.","Let red travel straight through the occupied cells along the top. Bend it after that stretch and look for a horizontal finish at the lower receiver."]],
  ["eia6d0",["Niebieski i zielony przechodzą przez różne wejścia gwiazdorozdzielaczy. Do cyjanowych celów doprowadź obie składowe; sprawdzaj po drodze osobne cele niebieskie i zielone.","Feed blue and green into different starburst inputs. Deliver both channels to cyan while checking the single-colour receivers along the way."]],
  ["1oyohfr",["Górne portale pozwalają przerzucić czerwień nad częścią z ciemnymi celami. Wychodzące odnogi skieruj do czerwonych celów dopiero za obszarem, który ma zostać ciemny.","The upper portals can take red past dense groups of dark receivers. Turn the exiting branches toward the red targets after the dark area."]],
  ["1plzzkj",["Gwiazdorozdzielacze obsługują lewy i prawy bok. Kieruj też odnogi ku środkowej bramce, która w tym układzie kończy ich przebieg bez zasilania ciemnych celów.","Use two starbursts to cover the left and right sides. Feed the middle gate so those branches stop short of the dark receivers."]],
  ["13w25jv",["Pryzmaty mają wydzielić pojedyncze kolory. Dopiero potem dobierz po dwa symetryczne dojścia do każdej bramki podstawowej, żeby miała dokładnie jeden wspólny kanał.","Use the prisms to isolate the primary colours. Then give each primary gate two symmetric arrivals with precisely one shared channel."]],
  ["1fdrf3s",["Splątana biel pozwala zbudować po dwie drogi dla każdej z trzech barw. Rozdziel widmo w pryzmatach i zaplanuj powroty do trzech bramek podstawowych parami.","Entangled white gives you two paths for each primary colour. Separate them with the prisms and plan their returns to the three primary gates in pairs."]],
  ["1rsiqtv",["Część bieli zachowaj dla lewego celu. W środku pryzmat wydzieli czerwień, a niebieski i zielony prowadź równoległymi drogami do cyjanowych celów.","Keep some white for the left receiver. The central prism isolates red, while parallel blue and green paths feed the cyan receivers."]],
  ["a151ji",["Rozdziel obie białe wiązki w osobnych pryzmatach. Czerwone i zielone wyjścia kieruj do najbliższych pasujących celów, pozostawiając niebieskiemu ukośne drogi po prawej.","Split the white beams with separate prisms. Route their red and green outputs toward matching receivers and reserve right-side diagonals for blue."]],
  ["vqnhc",["Komplementor ma dać trzy różne mieszanki z trzech różnych wejść. Skrętniki i dwustronne lustro wykorzystaj do ustawienia mieszanych wiązek w osiach kanałów.","Use three different complementor inputs to produce three mixed colours. Twisters and the dual reflector align the mixed beams with the conduits."]],
  ["e9jblx",["Przejdź od zielonego lasera do długiego odcinka w prawo u góry. Buduj powrót z drugiej strony przez przekątne, a potem użyj tej samej zasady przy dolnych rzędach.","Get green onto the long rightward run at the top. Build a diagonal return from the far side and reuse the idea at the lower rows."]],
  ["15adnhd",["Podaj do komplementora niebieski, czerwony i zielony różnymi osiami. Filtry pozwolą wyciągnąć z jego par składowe i ochronić pole, które ma zostać ciemne.","Feed blue, red and green to the complementor on different axes. Use filters to extract components from its mixtures and keep the dark receiver unlit."]],
  ["19v7n04",["Gwiazdorozdzielacze w górnych i dolnych narożnikach przejmują inne typy wejść. Wykorzystaj to, że prosty kierunek daje przekątne, a skos daje odnogi osiowe.","The upper and lower starbursts take different kinds of input. A straight input outputs diagonals, and a diagonal input outputs straight branches."]],
  ["zepuqs",["Najpierw wykorzystaj cztery źródła jako oddzielne obiegi. Ruchomy portal u prawej góry pozwoli zachować ukośny kierunek przy przejściu do kolejnego fragmentu.","Start by treating the four sources as separate loops. A movable portal at the upper right carries a diagonal heading into another part of the board."]],
  ["embqmu",["Zielony może zasilać swój środek pionowo, niebieski potrzebuje kilku dolnych odbić, a czerwony idzie własnymi skosami. Zacznij od rozdzielenia odnóg u góry.","Green can serve a central receiver vertically, blue needs several lower reflections, and red takes its own diagonals. Begin by establishing the upper branches."]],
 ])],
]);

export function classicStrategy(level,language){
 const campaign=strategies.get(level.sourceGame);
 return campaign?.get(packFingerprint([level]))?.[language==='en'?1:0] ?? null;
}
